const configText = $input.item.json.stdout || '{}';
const config = JSON.parse(configText);

const now = new Date();
const timestamp = now.toISOString().replace(/[:.]/g, '-').slice(0, 19);

return [{
  json: {
    jobTitles: config.job_titles || ['Engineering Manager'],
    location: config.location || 'London, UK',
    timeRange: config.time_range || '48h',
    minScore: config.min_score || 7,
    maxJobs: config.max_jobs_per_title || 20,
    ollamaModel: config.ollama_model || 'qwen2.5:latest',
    ollamaUrl: config.ollama_url || 'http://host.docker.internal:11434',
    runTimestamp: timestamp,
    outputFileMatches: `/data/n8n_linkedin/output/matches_${timestamp}.json`,
    outputFileRejected: `/data/n8n_linkedin/output/rejected_${timestamp}.json`,
    metadata: {
      source: 'LinkedIn',
      aiProvider: 'Ollama',
      aiModel: config.ollama_model || 'qwen2.5:latest',
      candidateName: 'Joao Lourenco',
      runDate: now.toISOString()
    }
  }
}];

const output = $input.item.json.stdout || '[]';
const config = $('Parse Config').item.json;
const searchTitle = $('Split Job Titles').item.json.jobTitles;

// Find JSON array in output (after any log messages)
let jobs = [];
const lines = output.split('\n');
for (const line of lines) {
  const trimmed = line.trim();
  if (trimmed.startsWith('[')) {
    try {
      jobs = JSON.parse(trimmed);
      break;
    } catch(e) {}
  }
}

if (!Array.isArray(jobs) || jobs.length === 0) {
  console.log('No jobs found for:', searchTitle);
  return [];
}

console.log(`Found ${jobs.length} jobs for: ${searchTitle}`);

return jobs.map(job => ({
  json: {
    job: {
      title: job.title || 'Unknown',
      company: job.company || 'Unknown',
      location: job.location || '',
      job_link: job.job_link || '',
      posted_date: job.posted_date || '',
      description: job.description || ''
    },
    searchTitle: searchTitle,
    config: config
  }
}));

const item = $input.item.json;
const job = item.job;
const config = item.config;

if (!job.description || job.description.length < 50) {
  console.log(`Skipping ${job.title} - no description`);
  return [];
}

const cleanDesc = job.description
  .substring(0, 2000)
  .replace(/[\x00-\x1F\x7F]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const systemPrompt = `You analyze job postings. Return only valid JSON.

CANDIDATE: Joao Lourenco - Engineering Manager, London
- 14+ years software quality, 8+ years leading teams
- Manager of managers: 16 people, 2 EMs
- Scaled teams 4→16, 100% UK retention
- Domains: safety-critical (auto/aero/defence)
- Skills: test automation, CI/CD, Python, ISO 9001/27001

REJECT: hands-on IC coding, hardware/embedded, mechanical/civil, junior roles, C-suite

SCORE: 9-10=perfect, 7-8=strong, 5-6=partial, 1-4=poor`;

const userPrompt = `Analyze: ${job.title} at ${job.company}

Description: ${cleanDesc}

Return JSON:
{"relevant":bool,"rejection_reason":str/null,"score":1-10,"company_industry":str,"role_summary":str,"match_reasons":[],"concerns":[],"seniority_level":str}`;

return [{
  json: {
    job: job,
    searchTitle: item.searchTitle,
    config: config,
    ollamaPayload: {
      model: config.ollamaModel,
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt }
      ],
      stream: false,
      options: { temperature: 0.3 }
    }
  }
}];

const item = $input.item.json;
const prev = $('Build Analyze Request').item.json;

let analysis = {
  relevant: false,
  rejection_reason: 'Parse failed',
  score: 0,
  company_industry: 'Unknown',
  role_summary: '',
  match_reasons: [],
  concerns: [],
  seniority_level: 'Unknown'
};

try {
  let text = item.message?.content || item.response || '';
  text = text.replace(/```json\n?/gi, '').replace(/```\n?/g, '').trim();
  const match = text.match(/\{[\s\S]*\}/);
  if (match) analysis = JSON.parse(match[0]);
} catch(e) {
  console.log('Parse error:', e.message);
}

analysis.score = parseInt(analysis.score) || 0;

return [{
  json: {
    job: prev.job,
    analysis: analysis,
    searchTitle: prev.searchTitle,
    config: prev.config,
    isMatch: analysis.relevant === true && analysis.score >= prev.config.minScore
  }
}];

const data = $input.item.json;
const job = data.job;
const analysis = data.analysis;
const config = data.config;

const userPrompt = `Write a cover letter for Joao Lourenco applying to:

Position: ${job.title}
Company: ${job.company}

Role: ${analysis.role_summary}
Match reasons: ${(analysis.match_reasons || []).join(', ')}

Candidate highlights:
- Engineering Manager, 14+ years
- Scaled teams 4→16 (manager of managers)
- 100% UK retention
- Safety-critical: auto/aero/defence
- Test automation transformation
- ISO 9001/27001

300-400 words. Address to Hiring Manager. Sign as Joao Lourenco.`;

return [{
  json: {
    job: job,
    analysis: analysis,
    searchTitle: data.searchTitle,
    config: config,
    ollamaPayload: {
      model: config.ollamaModel,
      messages: [
        { role: 'system', content: 'Write professional cover letters. Be concise.' },
        { role: 'user', content: userPrompt }
      ],
      stream: false,
      options: { temperature: 0.7 }
    }
  }
}];

const resp = $input.item.json;
const prev = $('Build Cover Request').item.json;

const coverLetter = resp.message?.content || resp.response || 'Error generating cover letter';

const record = {
  job: prev.job,
  analysis: prev.analysis,
  cover_letter: coverLetter.trim(),
  metadata: {
    ...prev.config.metadata,
    searchTitle: prev.searchTitle,
    processedAt: new Date().toISOString(),
    status: 'matched'
  }
};

const b64 = Buffer.from(JSON.stringify(record)).toString('base64');

return [{ json: { b64: b64, outputFile: prev.config.outputFileMatches } }];

const data = $input.item.json;

const record = {
  job: data.job || {},
  analysis: {
    relevant: data.analysis?.relevant || false,
    rejection_reason: data.analysis?.rejection_reason || `Score ${data.analysis?.score || 0} below min`,
    score: data.analysis?.score || 0,
    company_industry: data.analysis?.company_industry || 'Unknown',
    seniority_level: data.analysis?.seniority_level || 'Unknown'
  },
  metadata: {
    source: 'LinkedIn',
    searchTitle: data.searchTitle || '',
    processedAt: new Date().toISOString(),
    status: 'rejected'
  }
};

const b64 = Buffer.from(JSON.stringify(record)).toString('base64');

return [{ json: { b64: b64, outputFile: data.config?.outputFileRejected || '/data/n8n_linkedin/output/rejected.json' } }];
